import{_ as t,o as a,c as n,a3 as o}from"./chunks/framework.DQ-7HQaQ.js";const u=JSON.parse('{"title":"Plan your individual RAG","description":"Select a user, five permitted sources, a justified retrieval method and questions you can evaluate.","frontmatter":{"title":"Plan your individual RAG","description":"Select a user, five permitted sources, a justified retrieval method and questions you can evaluate."},"headers":[],"relativePath":"students/plan.md","filePath":"students/plan.md","lastUpdated":1794433168000}'),r={name:"students/plan.md"};function i(s,e,d,l,p,c){return a(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="plan-one-useful-source-backed-question" tabindex="-1">Plan one useful source-backed question <a class="header-anchor" href="#plan-one-useful-source-backed-question" aria-label="Permalink to &quot;Plan one useful source-backed question&quot;">​</a></h1><p>You do <strong>not</strong> need a working RAG application for the Plan review. You need a small, defensible design that you can build next. Reuse the portfolio, FastAPI app, server and Git workflow you already have where practical.</p><h2 id="_1-define-the-reader-and-the-question" tabindex="-1">1. Define the reader and the question <a class="header-anchor" href="#_1-define-the-reader-and-the-question" aria-label="Permalink to &quot;1. Define the reader and the question&quot;">​</a></h2><p>Complete: <strong>“My application helps [reader] answer [type of question] using [permitted content].”</strong></p><p>Good source domains are small and verifiable: fictional club policies, public product instructions with permitted use, your own tutorials, or synthetic help-center articles. Avoid private student records and other confidential information.</p><h2 id="_2-select-about-five-documents" tabindex="-1">2. Select about five documents <a class="header-anchor" href="#_2-select-about-five-documents" aria-label="Permalink to &quot;2. Select about five documents&quot;">​</a></h2><p>Keep one row per source: stable ID, title, origin/URL, author or owner, version/date, permission, and intended questions. Label synthetic content explicitly. A publicly readable document is not automatically licensed for redistribution.</p><h2 id="_3-compare-retrieval-approaches-before-choosing" tabindex="-1">3. Compare retrieval approaches before choosing <a class="header-anchor" href="#_3-compare-retrieval-approaches-before-choosing" aria-label="Permalink to &quot;3. Compare retrieval approaches before choosing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Good for</th><th>What to investigate</th></tr></thead><tbody><tr><td>Keyword/SQL baseline</td><td>Exact names, codes and phrases</td><td>Paraphrases can be missed</td></tr><tr><td>Vector</td><td>Semantically related passages</td><td>Similarity is not proof or identity</td></tr><tr><td>Graph</td><td>Named entities and typed relationships</td><td>Wrong/missing edges distort answers</td></tr><tr><td>Hybrid</td><td>Combining evidence types</td><td>Additional complexity needs justification</td></tr></tbody></table><p><strong>The assignment asks you to research vector and graph approaches, but you may implement vector, graph or both.</strong> Do not build an unused database to satisfy a diagram. Document which retrieval method you selected and why a simpler baseline might fail.</p><h2 id="_4-sketch-the-path" tabindex="-1">4. Sketch the path <a class="header-anchor" href="#_4-sketch-the-path" aria-label="Permalink to &quot;4. Sketch the path&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>permitted source → import/clean → chunk or graph representation</span></span>
<span class="line"><span>                 → persistent retrieval → question → context</span></span>
<span class="line"><span>                 → real model → answer + checkable references</span></span></code></pre></div><p>Specify how source IDs and locations survive each step. For vector retrieval, include embedding model/version and the query&#39;s compatible encoder. For graph retrieval, include entity types, relationship types and supporting passages.</p><h2 id="_5-write-expected-behavior-before-implementation" tabindex="-1">5. Write expected behavior before implementation <a class="header-anchor" href="#_5-write-expected-behavior-before-implementation" aria-label="Permalink to &quot;5. Write expected behavior before implementation&quot;">​</a></h2><p>Begin with five questions: exact-term, paraphrase, relationship (when relevant), ordinary useful, and intentionally unanswerable. Record the expected supporting sources <strong>before</strong> running the model.</p><p>Two essential checks: repeat import should not create unintended duplicates; missing evidence should not result in an invented answer.</p><h2 id="_6-record-one-decision-and-one-next-experiment" tabindex="-1">6. Record one decision and one next experiment <a class="header-anchor" href="#_6-record-one-decision-and-one-next-experiment" aria-label="Permalink to &quot;6. Record one decision and one next experiment&quot;">​</a></h2><p>Name two plausible approaches, your choice, costs or constraints, and a small experiment that might change your mind. Keep planned evidence labeled <em>planned</em> rather than claiming the test passed.</p><p>Use the existing <a href="https://github.com/kaw393939/is373-studio/blob/main/docs/templates/project-record.md" target="_blank" rel="noreferrer">project record</a> under <strong>2. Individual RAG app + technical research</strong>. <a href="./prompts#plan-prompt">Copy the Plan agent prompt</a>.</p>`,19)])])}const m=t(r,[["render",i]]);export{u as __pageData,m as default};
